package com.johnny.hotel.extras;import org.apache.ibatis.annotations.*;import java.util.*;
@Mapper public interface ExtrasMapper{
 @Insert("INSERT INTO charge_catalog(code,name,charge_type,category,unit_price,status,description) VALUES(#{code},#{name},#{chargeType},#{category},#{unitPrice},#{status},#{description})")@Options(useGeneratedKeys=true,keyProperty="id")int insertCatalog(ChargeCatalog c);
 @Select("SELECT * FROM charge_catalog WHERE id=#{id}")ChargeCatalog catalog(Long id);@Select("SELECT * FROM charge_catalog WHERE id=#{id} FOR UPDATE")ChargeCatalog lockCatalog(Long id);
 @Update("UPDATE charge_catalog SET name=#{name},charge_type=#{chargeType},category=#{category},unit_price=#{unitPrice},description=#{description} WHERE id=#{id}")int updateCatalog(ChargeCatalog c);
 @Update("UPDATE charge_catalog SET status=#{status} WHERE id=#{id} AND status=#{expected}")int catalogStatus(@Param("id")Long id,@Param("expected")int expected,@Param("status")int status);
 @Select("<script>SELECT * FROM charge_catalog <where><if test='type!=null'>charge_type=#{type}</if><if test='status!=null'> AND status=#{status}</if><if test='q!=null'> AND (code LIKE CONCAT('%',#{q},'%') OR name LIKE CONCAT('%',#{q},'%') OR category LIKE CONCAT('%',#{q},'%'))</if></where> ORDER BY create_time DESC,id DESC LIMIT #{offset},#{size}</script>")List<ChargeCatalog> catalogPage(@Param("type")Integer type,@Param("status")Integer status,@Param("q")String q,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM charge_catalog <where><if test='type!=null'>charge_type=#{type}</if><if test='status!=null'> AND status=#{status}</if><if test='q!=null'> AND (code LIKE CONCAT('%',#{q},'%') OR name LIKE CONCAT('%',#{q},'%') OR category LIKE CONCAT('%',#{q},'%'))</if></where></script>")long catalogCount(@Param("type")Integer type,@Param("status")Integer status,@Param("q")String q);
 @Insert("INSERT INTO guest_service_order(booking_id,folio_id,customer_user_id,catalog_id,task_id,catalog_code_snapshot,name_snapshot,unit_price_snapshot,quantity,amount,request_note,request_key,status,requested_by) VALUES(#{bookingId},#{folioId},#{customerUserId},#{catalogId},#{taskId},#{catalogCodeSnapshot},#{nameSnapshot},#{unitPriceSnapshot},#{quantity},#{amount},#{requestNote},#{requestKey},#{status},#{requestedBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertService(GuestServiceOrder o);
 @Select("SELECT * FROM guest_service_order WHERE requested_by=#{actor} AND request_key=#{key}")GuestServiceOrder serviceByKey(@Param("actor")Long actor,@Param("key")String key);
 @Select("SELECT * FROM guest_service_order WHERE id=#{id}")GuestServiceOrder service(Long id);@Select("SELECT * FROM guest_service_order WHERE id=#{id} FOR UPDATE")GuestServiceOrder lockService(Long id);
 @Select("SELECT * FROM guest_service_order WHERE task_id=#{taskId} FOR UPDATE")GuestServiceOrder serviceByTask(Long taskId);
 @Update("UPDATE guest_service_order SET status=1 WHERE id=#{id} AND status=0")int serviceStarted(Long id);
 @Update("UPDATE guest_service_order SET status=2,folio_item_id=#{item},completed_by=#{actor},completed_time=CURRENT_TIMESTAMP(6) WHERE id=#{id} AND status IN (0,1) AND folio_item_id IS NULL")int completeService(@Param("id")Long id,@Param("item")Long item,@Param("actor")Long actor);
 @Update("UPDATE guest_service_order SET status=3,cancelled_by=#{actor},cancelled_time=CURRENT_TIMESTAMP(6) WHERE id=#{id} AND status IN (0,1) AND folio_item_id IS NULL")int cancelService(@Param("id")Long id,@Param("actor")Long actor);
 @Select("<script>SELECT * FROM guest_service_order <where><if test='booking!=null'>booking_id=#{booking}</if><if test='customer!=null'> AND customer_user_id=#{customer}</if><if test='status!=null'> AND status=#{status}</if></where> ORDER BY create_time DESC,id DESC LIMIT #{offset},#{size}</script>")List<GuestServiceOrder> servicePage(@Param("booking")Long booking,@Param("customer")Long customer,@Param("status")Integer status,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM guest_service_order <where><if test='booking!=null'>booking_id=#{booking}</if><if test='customer!=null'> AND customer_user_id=#{customer}</if><if test='status!=null'> AND status=#{status}</if></where></script>")long serviceCount(@Param("booking")Long booking,@Param("customer")Long customer,@Param("status")Integer status);
 @Insert("INSERT INTO guest_purchase(booking_id,folio_id,customer_user_id,request_key,status,total_amount,requested_by) VALUES(#{bookingId},#{folioId},#{customerUserId},#{requestKey},#{status},#{totalAmount},#{requestedBy})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPurchase(GuestPurchase p);
 @Insert("INSERT INTO guest_purchase_item(purchase_id,catalog_id,catalog_code_snapshot,name_snapshot,unit_price_snapshot,quantity,amount) VALUES(#{purchaseId},#{catalogId},#{catalogCodeSnapshot},#{nameSnapshot},#{unitPriceSnapshot},#{quantity},#{amount})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPurchaseItem(GuestPurchaseItem i);
 @Select("SELECT * FROM guest_purchase WHERE requested_by=#{actor} AND request_key=#{key}")GuestPurchase purchaseByKey(@Param("actor")Long actor,@Param("key")String key);
 @Select("SELECT * FROM guest_purchase WHERE id=#{id}")GuestPurchase purchase(Long id);@Select("SELECT * FROM guest_purchase WHERE id=#{id} FOR UPDATE")GuestPurchase lockPurchase(Long id);
 @Select("SELECT * FROM guest_purchase_item WHERE purchase_id=#{id} ORDER BY id FOR UPDATE")List<GuestPurchaseItem> purchaseItems(Long id);
 @Update("UPDATE guest_purchase SET status=1,confirmed_by=#{actor},confirmed_time=CURRENT_TIMESTAMP(6) WHERE id=#{id} AND status=0")int confirmPurchase(@Param("id")Long id,@Param("actor")Long actor);
 @Update("UPDATE guest_purchase_item SET folio_item_id=#{folioItem} WHERE id=#{id} AND folio_item_id IS NULL")int linkPurchaseItem(@Param("id")Long id,@Param("folioItem")Long folioItem);
 @Update("UPDATE guest_purchase SET status=2,cancelled_by=#{actor},cancelled_time=CURRENT_TIMESTAMP(6) WHERE id=#{id} AND status=0")int cancelPurchase(@Param("id")Long id,@Param("actor")Long actor);
 @Select("<script>SELECT * FROM guest_purchase <where><if test='booking!=null'>booking_id=#{booking}</if><if test='customer!=null'> AND customer_user_id=#{customer}</if><if test='status!=null'> AND status=#{status}</if></where> ORDER BY create_time DESC,id DESC LIMIT #{offset},#{size}</script>")List<GuestPurchase> purchasePage(@Param("booking")Long booking,@Param("customer")Long customer,@Param("status")Integer status,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM guest_purchase <where><if test='booking!=null'>booking_id=#{booking}</if><if test='customer!=null'> AND customer_user_id=#{customer}</if><if test='status!=null'> AND status=#{status}</if></where></script>")long purchaseCount(@Param("booking")Long booking,@Param("customer")Long customer,@Param("status")Integer status);
 @Select("SELECT * FROM guest_service_order WHERE folio_id=#{folio} ORDER BY id FOR UPDATE")List<GuestServiceOrder> servicesForFolio(Long folio);
 @Select("SELECT * FROM guest_purchase WHERE folio_id=#{folio} ORDER BY id FOR UPDATE")List<GuestPurchase> purchasesForFolio(Long folio);
 @Select("SELECT i.* FROM guest_purchase_item i JOIN guest_purchase p ON p.id=i.purchase_id WHERE p.folio_id=#{folio} ORDER BY i.id FOR UPDATE")List<GuestPurchaseItem> purchaseItemsForFolio(Long folio);
}
